use std::fs

fn best(prios: Vec<int>) -> int {
    let mut bi: int = -1
    let n: int = prios.len() as int
    let mut i: int = 0
    while i < n {
        if bi < 0 || prios[i as usize] > prios[bi as usize] {
            bi = i
        }
        i += 1
    }
    bi
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut names: Vec<string> = []
    let mut prios: Vec<int> = []
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            println("error")
        } else if parts[0] == "add" && parts.len() == 3 {
            match parts[2].parse::<int>() {
                Ok(p) => {
                    names.push(parts[1])
                    prios.push(p)
                }
                Err(_) => println("error")
            }
        } else if parts[0] == "pop" && parts.len() == 1 {
            let b = best(prios)
            if b < 0 {
                println("empty")
            } else {
                println(names[b as usize])
                names.remove(b as usize)
                prios.remove(b as usize)
            }
        } else if parts[0] == "peek" && parts.len() == 1 {
            let b = best(prios)
            if b < 0 {
                println("empty")
            } else {
                println(names[b as usize])
            }
        } else if parts[0] == "size" && parts.len() == 1 {
            println("${names.len()}")
        } else {
            println("error")
        }
    }
    println("left:")
    loop {
        let b = best(prios)
        if b < 0 {
            break
        }
        println("${names[b as usize]} ${prios[b as usize]}")
        names.remove(b as usize)
        prios.remove(b as usize)
    }
}

